impl SparseTensor {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsSparseTensor<'a>> {
        use crate::types::generated::SparseTensor_generated::SparseTensorBuilder as FbsSparseTensorBuilder;

        let mut shape_offsets = Vec::with_capacity(self.shape.len());
        for val in self.shape.iter() {
            let offset = val.serialize_to(builder);
            shape_offsets.push(offset);
        }
        let shape_offset = builder.create_vector(&shape_offsets);
        let (sparseIndex_offset, sparseIndex_ty) = self.sparseIndex.serialize_to(builder);
        let (type__offset, type__ty) = self.type_.serialize_to(builder);

        let mut bldr = FbsSparseTensorBuilder::new(builder);
        let data: FbsBuffer = self.data.clone().into();
        bldr.add_data(&data);
        bldr.add_non_zero_length(self.non_zero_length);
        bldr.add_shape(shape_offset);
        bldr.add_sparseIndex(sparseIndex_offset);
        bldr.add_sparseIndex_type(sparseIndex_ty);
        bldr.add_type_(type__offset);
        bldr.add_type_type(type__ty);
        bldr.finish()
    }
}

